-- EMERGENCY ROLLBACK 079 (production). Generated by docs/releases/production-075/gen-emergency-rollback.py.
-- Run ONLY with the owner's approval, in ONE transaction:
--   psql "<production connection>" -X -v ON_ERROR_STOP=1 --single-transaction -f docs/releases/production-075/emergency/rollback_079_with_history.sql
-- Order: newest first (081, 080, 079, 078, 077, 076, 075, 074, 073). Keeps every business row; removes the 079 history row so the migration history
-- matches the schema again (the plain supabase/rollback file does not touch supabase_migrations).
set lock_timeout = '10s';
set statement_timeout = '5min';
do $guard$
begin
  if to_regprocedure('public.deployment_environment()') is not null then
    raise exception 'STOP: JewelryFlow SaaS demo database, not Goldia';
  end if;
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20260101000079') then
    raise exception 'STOP: migration 079 is not recorded — nothing to roll back';
  end if;
  if exists (select 1 from supabase_migrations.schema_migrations where version > '20260101000079') then
    raise exception 'STOP: a newer migration is recorded — roll that back first';
  end if;
end $guard$;

-- ===== supabase/rollback/20260101000079_rollback.sql =====
-- ROLLBACK of 079 (D-A1 archived-customer sale block, D-A2 assignment guard). Drops the two guard triggers and their
-- functions only; no row is changed. Keeps the history row (like the other supabase/rollback files; the emergency
-- variant removes it). After it, sales to archived customers and seller self-assignment by direct write are possible again.
drop trigger if exists trg_goldia_guard_sale_archived_customer on public.jewelry_sales;
drop function if exists public._goldia_guard_sale_archived_customer();
drop trigger if exists trg_goldia_guard_customer_assignment on public.customers;
drop function if exists public._goldia_guard_customer_assignment();
notify pgrst, 'reload schema';

;
reset all;
delete from supabase_migrations.schema_migrations where version = '20260101000079';
